"""CATEGORY G - DIGITAL SEARCHES (scenarios 44-55).

Every row carries the five-question Phone Search Framework in Research_Notes:
  Q1 seizure authorised?  Q2 inspection authorised?  Q3 password compulsion?
  Q4 biometric unlock?    Q5 cloud access?
"""
from .common import *  # noqa: F401,F403

CAT = "G - Digital Searches"

S116B = ("CPC s.116B(1): 'A police officer not below the rank of Inspector conducting a search under this Code shall be given access to computerized data whether stored in a computer or otherwise.' "
         "s.116B(3): '\"access\" includes being provided with the necessary password, encryption code, decryption code, software or hardware and any other means required to enable comprehension of the computerized data.' "
         "s.116B(2): information so obtained is admissible notwithstanding any other written law.")
CMA_NOTE = ("Communications and Multimedia Act 1998 (Act 588) - commonly cited for s.233 (improper use of network facilities), s.247 (search by warrant), s.248 (search without warrant), s.249 (access to computerised data incl. passwords) and s.252 (interception) - was NOT supplied; the file labelled MCMC is Act 589 (the Commission Act), which contains only s.49 (investigating officers' powers). All CMA 1998 references are Requires Independent Verification.")

def framework(q1, q2, q3, q4, q5, extra=""):
    return j(
        "PHONE SEARCH FRAMEWORK - Q1 Seizure clearly authorised? " + q1,
        "Q2 Inspection clearly authorised? " + q2,
        "Q3 Password compulsion clearly authorised? " + q3,
        "Q4 Biometric (fingerprint/FaceID) unlock clearly authorised? " + q4,
        "Q5 Cloud account access clearly authorised? " + q5,
        extra, CMA_NOTE,
    )

Q1_YES = "YES in context - on arrest (CPC s.20: articles found on the person; 'reason to believe' instrument/evidence); during a lawful premises search (s.56 warrant / s.116 / s.116A(1)(a)); CCA s.10(1) 'seize and detain any such evidence'; AMLA s.31(1)(d); MACC s.31(1)(a). NO stand-alone street power to take a phone from a non-arrested person."
Q2_PARTIAL = "PARTLY - s.116B gives Inspector+ 'conducting a search under this Code' access to computerised data; CCA s.10(1)(a) warrant holder may 'have access to any program or data held in any computer'. Whether seizure of a phone on arrest (s.20) by itself permits content inspection without a search under Chapter VI/XIII is NOT explicit - Requires Case Law Review."
Q3_PARTIAL = "PARTLY - s.116B(3) defines access to include 'being provided with the necessary password'; CCA s.10(1)(b) 'reasonable assistance'; s.116B/CCA are silent on the penalty for the suspect's refusal and on the privilege against self-incrimination. Compulsion of a SUSPECT (vs. a third-party custodian) - Legal Position Not Explicitly Stated In Statute Reviewed; Requires Case Law Review. Obstruction offences (PC s.186; CCA s.11(1)(b) 'fails to comply with any lawful demands'; CMA s.249 if applicable) may be relied on by police."
Q4_NO = "NOT EXPLICIT - no statute reviewed mentions fingerprint, face or other biometric unlocking; s.116B(3) 'any other means required to enable comprehension' could be argued to cover it. Legal Position Not Explicitly Stated In Statute Reviewed; Requires Case Law Review."
Q5_NO = "NOT EXPLICIT - s.116B refers to data 'stored in a computer or otherwise'; CCA s.10(1)(c) covers information 'contained in a computer and accessible from the premises'; neither expressly addresses remote/cloud accounts hosted abroad; interception of communications in transit requires PP authorisation (CPC s.116C; SOSMA s.6; MACC s.43). Requires Case Law Review."

DIGITAL_QUESTIONS = j(
    "Am I under arrest? If not, under which section are you taking/inspecting my phone?",
    "Which offence is being investigated and what is the report number?",
    "Is this a search under the CPC conducted by an officer of or above Inspector rank? (s.116B)",
    "Please give me a seizure list/receipt for the device (CPC s.64-65; Sch.4 para 6(k)(ii))",
    "I do not consent to a search of my device; I will not obstruct. Please record my objection.",
    "I wish to call a lawyer before answering questions about passwords (Red Book 11.3; CPC s.28A)",
)
DIGITAL_VERIFY = j(
    ID_CHECK,
    "Ask the officer to state the power (arrest s.20 / search warrant / s.116 / s.116A / s.116B / CCA s.10 / other Act)",
    "Ask for the rank of the officer demanding access (s.116B requires Inspector+)",
    "Request to be taken to the nearest police station for any phone check (Red Book 11.3) and call a lawyer",
    "Note IMEI/serial, time taken, condition, whether unlocked, apps opened",
)
DIGITAL_EVIDENCE = j(
    "Device make/model/IMEI; time and place of seizure; seizure receipt",
    "Whether device was unlocked and by whom; which apps/accounts were opened",
    "Officer names/ranks and the power cited",
    "Account login/activity logs from providers (Google/Apple/WhatsApp/Telegram security logs) showing access times",
    "Witnesses",
)

